class Solution {
public:
    vector<int> leftmostBuildingQueries(vector<int>& heights, vector<vector<int>>& queries) {
        int n = heights.size();
        int m = queries.size();
        vector<int> ans(m, -1);

        vector<vector<pair<int,int>>> byB(n);
        for (int qi = 0; qi < m; qi++) {
            int a = queries[qi][0], b = queries[qi][1];
            if (a > b) swap(a, b);
            if (a == b) {
                ans[qi] = a;
            } else if (heights[a] < heights[b]) {
                ans[qi] = b;
            } else {
                byB[b].push_back({a, qi});
            }
        }

        vector<int> stk;
        for (int i = n - 1; i >= 0; i--) {
            while (!stk.empty() && heights[stk.back()] <= heights[i]) {
                stk.pop_back();
            }
            stk.push_back(i);

            for (auto& [a, qi] : byB[i]) {
                int lo = 0, hi = (int)stk.size() - 1, res = -1;
                while (lo <= hi) {
                    int mid = (lo + hi) / 2;
                    if (heights[stk[mid]] > heights[a]) {
                        res = stk[mid];
                        lo = mid + 1;
                    } else {
                        hi = mid - 1;
                    }
                }
                ans[qi] = res;
            }
        }

        return ans;
    }
};
